class Resource extends Base {
 mount(){this.left=this.number('start',24,15,35);this.right=24;this.tab='main';this.files=[{name:'index.html',code:'<main class="studio">\n  <h1>A little room for an idea.</h1>\n  <p>Make something considered.</p>\n</main>'},{name:'styles.css',code:'.studio {\n  max-width: 64rem;\n  margin: auto;\n  padding: 3rem;\n  color: #263d32;\n}'},{name:'notes.md',code:'# Working notes\n\nStart with the useful part.\nGive every detail a reason to stay.\nLeave room for someone else.'}];this.file=0;this.render(`<section class="workspace"><header class="row between"><span><i></i> FIELDWORK / WORKSPACE</span><span class="saved">Local example</span></header><nav class="mobile-tabs" aria-label="Workspace panes"><button data-tab="sidebar" aria-pressed="false">Files</button><button data-tab="main" aria-pressed="true">Editor</button><button data-tab="inspector" aria-pressed="false">Inspector</button></nav><div class="panes"><aside class="sidebar" data-pane="sidebar"><slot name="sidebar"><span class="label">PROJECT FILES</span><div class="files">${this.files.map((f,i)=>`<button data-file="${i}" aria-pressed="${i===0}"><span>${i===0?'◇':i===1?'⌘':'≡'}</span>${escape(f.name)}</button>`).join('')}</div><span class="folder-note">3 files / one small idea</span></slot></aside><div class="divider" role="separator" aria-label="Resize file pane" aria-orientation="vertical" tabindex="0" data-divider="left"></div><main data-pane="main"><slot name="main"><div class="editor-title"><span data-title>index.html</span><small>EDITABLE VIEW</small></div><pre tabindex="0" aria-label="Selected file contents"><code></code></pre><div class="editor-status"><span>UTF-8</span><span data-lines></span></div></slot></main><div class="divider" role="separator" aria-label="Resize inspector pane" aria-orientation="vertical" tabindex="0" data-divider="right"></div><aside class="inspector" data-pane="inspector"><slot name="inspector"><span class="label">READING PREFERENCES</span><label><span>Wrap lines</span><input type="checkbox" data-wrap checked/></label><label><span>Show line numbers</span><input type="checkbox" data-numbers checked/></label><div class="inspector-note"><span>↔</span><p>Make room for what you’re working on. Dividers support dragging and arrow keys.</p></div></slot></aside></div><footer class="row between"><span>YOUR CONTENT. YOUR SPACE.</span><output></output></footer></section>`,`.workspace{border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;background:var(--bg);container-type:inline-size}header{padding:17px 20px;background:var(--panel);border-bottom:1px solid var(--line);font-size:9px;letter-spacing:1px}header>span:first-child{display:flex;gap:9px;align-items:center}header i{width:5px;height:5px;border-radius:50%;background:var(--accent)}.saved{font-size:9px;letter-spacing:0;color:var(--muted)}.panes{display:grid;grid-template-columns:var(--left,24%) 6px minmax(0,1fr) 6px var(--right,24%);min-height:365px}.sidebar,.inspector{padding:24px 14px;min-width:0}.label{font-size:8px;letter-spacing:1px}.files{display:flex;flex-direction:column;gap:5px;margin-top:18px}.files button{display:flex;gap:10px;align-items:center;background:none;border:0;text-align:left;font-size:11px;padding:9px 8px;color:var(--muted)}.files [aria-pressed=true]{background:#c6e6b00d;color:var(--accent)}.files button>span{font-size:13px}.folder-note{display:block;color:var(--muted);font-size:8px;margin:24px 8px}.divider{background:var(--line);cursor:col-resize;position:relative;touch-action:none}.divider::after{content:'';position:absolute;left:2px;top:45%;width:2px;height:30px;background:#839b8266;border-radius:2px}.divider:hover,.divider:focus-visible{background:var(--accent)}main{min-width:0;display:flex;flex-direction:column}.editor-title{padding:20px 18px;display:flex;justify-content:space-between;align-items:center;gap:10px;border-bottom:1px solid var(--line);font:11px ui-monospace}.editor-title small{font:6px system-ui;color:var(--muted);letter-spacing:1px}pre{margin:0;padding:22px 16px;font:11px/2 ui-monospace,monospace;white-space:pre-wrap;overflow:auto;min-height:265px;color:var(--accent);counter-reset:line}code>span{display:block;min-height:1em}code>span::before{counter-increment:line;content:counter(line);display:inline-block;width:25px;color:var(--muted);opacity:.5;user-select:none}pre.no-numbers code>span::before{display:none}.editor-status{display:flex;justify-content:space-between;margin-top:auto;padding:12px 18px;font-size:8px;color:var(--muted);border-top:1px solid var(--line)}.inspector label{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:10px;color:var(--muted);margin-top:22px}.inspector-note{margin-top:30px;padding-top:20px;border-top:1px solid var(--line)}.inspector-note>span{font-size:24px;color:var(--accent)}.inspector-note p{font-size:10px;line-height:1.8;color:var(--muted);margin-top:12px}footer{padding:13px 19px;border-top:1px solid var(--line);font-size:7px;letter-spacing:1px;color:var(--muted)}output{font:9px ui-monospace;color:var(--accent)}.mobile-tabs{display:none}@container(max-width:560px){.mobile-tabs{display:flex;border-bottom:1px solid var(--line);padding:7px 12px;gap:5px}.mobile-tabs button{flex:1;border:0;background:none;font-size:11px;padding:10px;color:var(--muted)}.mobile-tabs button[aria-pressed=true]{background:var(--panel);color:var(--accent)}.panes{display:block;min-height:320px}.divider{display:none}[data-pane]{display:none;min-height:320px}[data-pane].active-pane{display:block}pre{min-height:235px}header{font-size:8px}footer{font-size:6px}}`);this.$('main').classList.add('active-pane');this.listen(this.shadowRoot,'click',e=>{const file=e.target.closest('[data-file]');if(file){this.file=Number(file.dataset.file);this.paintFile();}const tab=e.target.closest('[data-tab]');if(tab){this.tab=tab.dataset.tab;this.$$('[data-tab]').forEach(n=>n.setAttribute('aria-pressed',String(n===tab)));this.$$('[data-pane]').forEach(n=>n.classList.toggle('active-pane',n.dataset.pane===this.tab));}});this.listen(this.$('[data-wrap]'),'change',e=>this.$('pre').style.whiteSpace=e.target.checked?'pre-wrap':'pre');this.listen(this.$('[data-numbers]'),'change',e=>this.$('pre').classList.toggle('no-numbers',!e.target.checked));for(const divider of this.$$('.divider')){this.listen(divider,'pointerdown',e=>{divider.setPointerCapture(e.pointerId);this.drag=divider.dataset.divider;});this.listen(divider,'pointermove',e=>{if(this.drag){const box=this.$('.panes').getBoundingClientRect();this.resizePane(this.drag,(this.drag==='left'?e.clientX-box.left:box.right-e.clientX)/box.width*100);}});this.listen(divider,'pointerup',()=>this.drag=null);this.listen(divider,'pointercancel',()=>this.drag=null);this.listen(divider,'keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const key=divider.dataset.divider;const step=(e.shiftKey?5:1)*(e.key==='ArrowRight'?1:-1)*(key==='right'?-1:1);this.resizePane(key,e.key==='Home'?15:e.key==='End'?35:this[key]+step);});}this.paintFile();this.paint();}
 resizePane(key,value){this[key]=clamp(value,15,35);if(this.left+this.right>65)this[key]=65-this[key==='left'?'right':'left'];this.paint();this.emit('layout-change',this.sizes);}
 paint(){this.$('.panes').style.setProperty('--left',`${this.left}%`);this.$('.panes').style.setProperty('--right',`${this.right}%`);this.$$('separator,.divider').forEach(n=>{n.setAttribute('aria-valuemin','15');n.setAttribute('aria-valuemax','35');n.setAttribute('aria-valuenow',String(Math.round(this[n.dataset.divider])));n.setAttribute('aria-valuetext',`${Math.round(this[n.dataset.divider])} percent`);});this.$('output').textContent=`${Math.round(this.left)} / ${Math.round(100-this.left-this.right)} / ${Math.round(this.right)}`;}
 paintFile(){const file=this.files[this.file];this.$('[data-title]').textContent=file.name;this.$('code').innerHTML=file.code.split('\n').map(line=>`<span>${escape(line)||' '}</span>`).join('');this.$('[data-lines]').textContent=`${file.code.split('\n').length} lines`;this.$$('[data-file]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===this.file)));}
 get sizes(){return{left:this.left,right:this.right};}
 configured(name){if(name==='start')this.resizePane('left',this.number('start',24,15,35));}
}
